import pandas as pd
import numpy as np # Added for potential numerical operations
import os

from sklearn.model_selection import train_test_split, GridSearchCV
from sklearn.preprocessing import StandardScaler, OneHotEncoder
from sklearn.compose import make_column_transformer
from sklearn.pipeline import make_pipeline
from xgboost import XGBClassifier # Changed to Classifier
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, roc_auc_score # Classification metrics
import joblib
import mlflow

# Define paths for the split data generated by prep.py
X_TRAIN_PATH = 'Xtrain.csv'
X_TEST_PATH = 'Xtest.csv'
Y_TRAIN_PATH = 'ytrain.csv'
Y_TEST_PATH = 'ytest.csv'

# Load the split datasets
X_train = pd.read_csv(X_TRAIN_PATH)
X_test = pd.read_csv(X_TEST_PATH)
y_train = pd.read_csv(Y_TRAIN_PATH)
y_test = pd.read_csv(Y_TEST_PATH)

print("Train and test data loaded successfully:")
print(f"X_train shape: {X_train.shape}")
print(f"X_test shape: {X_test.shape}")
print(f"y_train shape: {y_train.shape}")
print(f"y_test shape: {y_test.shape}")

# Identify numerical and categorical features based on the cleaned data (from prep.py)
# Assuming 'ProdTaken' is the target and CustomerID is already dropped.
# These should match the feature types in X_train after prep.py processing.

numerical_features = X_train.select_dtypes(include=np.number).columns.tolist()
categorical_features = X_train.select_dtypes(include='object').columns.tolist()

# Preprocessor: Scale numerical features and one-hot encode categorical features
preprocessor = make_column_transformer(
    (StandardScaler(), numerical_features),
    (OneHotEncoder(handle_unknown='ignore'), categorical_features)
)

# Define base XGBoost Classifier model
xgb_model = XGBClassifier(random_state=42, use_label_encoder=False, eval_metric='logloss', n_jobs=-1) # Removed n_jobs for potential platform compatibility issues with -1 in some envs

# Hyperparameter grid for XGBClassifier
param_grid = {
    'xgbclassifier__n_estimators': [100, 200], # Increased estimator count for better performance
    'xgbclassifier__max_depth': [3, 5, 7],
    'xgbclassifier__learning_rate': [0.05, 0.1, 0.2],
    'xgbclassifier__subsample': [0.7, 0.9],
    'xgbclassifier__colsample_bytree': [0.7, 0.9],
    'xgbclassifier__gamma': [0, 0.1] # Added gamma for regularization
}

# Create a pipeline with preprocessor and XGBoost Classifier
model_pipeline = make_pipeline(preprocessor, xgb_model)

# Start MLflow run for experiment tracking
with mlflow.start_run():
    # Grid Search with cross-validation for hyperparameter tuning
    # Using 'roc_auc' as scoring metric for binary classification
    grid_search = GridSearchCV(
        model_pipeline, 
        param_grid, 
        cv=3, 
        n_jobs=-1, 
        scoring='roc_auc' # Changed scoring to roc_auc for classification
    )
    grid_search.fit(X_train, y_train)

    # Log parameter sets for all trials within the grid search
    results = grid_search.cv_results_
    for i in range(len(results['params'])):
        param_set = results['params'][i]
        mean_score = results['mean_test_score'][i]

        with mlflow.start_run(nested=True):
            mlflow.log_params({k.replace('xgbclassifier__', ''): v for k, v in param_set.items()})
            mlflow.log_metric("mean_roc_auc_score", mean_score)

    # Log best parameters and score from GridSearchCV
    mlflow.log_params({k.replace('xgbclassifier__', ''): v for k, v in grid_search.best_params_.items()})
    mlflow.log_metric("best_roc_auc", grid_search.best_score_)

    best_model = grid_search.best_estimator_
    mlflow.sklearn.log_model(best_model, "best_xgboost_model")

    # Evaluate the best model on the training and test sets
    y_train_pred = best_model.predict(X_train)
    y_train_proba = best_model.predict_proba(X_train)[:, 1] # Probability for ROC AUC
    y_test_pred = best_model.predict(X_test)
    y_test_proba = best_model.predict_proba(X_test)[:, 1]

    # Calculate classification metrics
    train_accuracy = accuracy_score(y_train, y_train_pred)
    test_accuracy = accuracy_score(y_test, y_test_pred)
    train_precision = precision_score(y_train, y_train_pred)
    test_precision = precision_score(y_test, y_test_pred)
    train_recall = recall_score(y_train, y_train_pred)
    test_recall = recall_score(y_test, y_test_pred)
    train_f1 = f1_score(y_train, y_train_pred)
    test_f1 = f1_score(y_test, y_test_pred)
    train_roc_auc = roc_auc_score(y_train, y_train_proba)
    test_roc_auc = roc_auc_score(y_test, y_test_proba)

    # Log metrics to MLflow
    mlflow.log_metrics({
        "train_accuracy": train_accuracy,
        "test_accuracy": test_accuracy,
        "train_precision": train_precision,
        "test_precision": test_precision,
        "train_recall": train_recall,
        "test_recall": test_recall,
        "train_f1": train_f1,
        "test_f1": test_f1,
        "train_roc_auc": train_roc_auc,
        "test_roc_auc": test_roc_auc,
    })

    print("\n--- Model Evaluation Results ---")
    print(f"Train Accuracy: {train_accuracy:.4f}")
    print(f"Test Accuracy: {test_accuracy:.4f}")
    print(f"Train Precision: {train_precision:.4f}")
    print(f"Test Precision: {test_precision:.4f}")
    print(f"Train Recall: {train_recall:.4f}")
    print(f"Test Recall: {test_recall:.4f}")
    print(f"Train F1-Score: {train_f1:.4f}")
    print(f"Test F1-Score: {test_f1:.4f}")
    print(f"Train ROC AUC: {train_roc_auc:.4f}")
    print(f"Test ROC AUC: {test_roc_auc:.4f}")

    # Save the best model locally for deployment
    deployment_path = "tourism_project/deployment"
    os.makedirs(deployment_path, exist_ok=True)
    model_save_path = os.path.join(deployment_path, "model.joblib")
    joblib.dump(best_model, model_save_path)
    print(f"\nBest model saved to {model_save_path}")
